int island_perimeter(std::vector<std::vector<int>>& grid) {
	int perimeter = 0;
	for (int r = 0; r < grid.size(); ++r) {
		for (int c = 0; c < grid[0].size(); ++c) {
			if (grid[r][c] == 1) {
