#include <vector>

int find_intersection_sorted_triplet(const std::vector<int>& a, const std::vector<int>& b, const std::vector<int>& c) {
	size_t i = 0, j = 0, k = 0;
	while (i < a.size() && j < b.size() && k < c.size()) {
		if (a[i] == b[j] && b[j] == c[k]) return a[i];
		if (a[i] < b[j]) i++;
		else if (b[j] < c[k]) j++;
		else k++;
	}
	return -1;
}
---
Triple nested loops lead to $O(n \cdot m \cdot p)$ complexity. For sorted arrays, a three-pointer approach finds common elements in $O(n + m + p)$ linear time by incrementing the pointer of the smallest current value.

