bool is_rotation(const std::vector<int>& a, const std::vector<int>& b) {
	if (a.size() != b.size()) return false;
	int n = a.size();
	for (int start = 0; start < n; ++start) {
		bool match = true;
		for (int i = 0; i < n; ++i) {
			if (a[i] != b[(start + i) % n]) {
				match = false; break;
			}
		}
		if (match) return true;
	}
	return false;
}

output:
