output:
#include <vector>

int find_index_in_rotated_sorted(const std::vector<int>& nums, int target) {
	int low = 0, high = (int)nums.size() - 1;
	while (low <= high) {
		int mid = low + (high - low) / 2;
		if (nums[mid] == target) return mid;
		if (nums[low] <= nums[mid]) {
			if (target >= nums[low] && target < nums[mid]) high = mid - 1;
			else low = mid + 1;
		} else {
			if (target > nums[mid] && target <= nums[high]) low = mid + 1;
			else high = mid - 1;
		}
	}
	return -1;
}
---
Linear search takes $O(n)$ time. A modified binary search can determine which half of the rotated array is sorted and perform elimination, reducing complexity to $O(\log n)$.

