std::vector<int> get_even_sorted(std::vector<int>& nums) {
	nums.erase(std::remove_if(nums.begin(), nums.end(), [](int x) { return x % 2 != 0; }), nums.end());
	std::sort(nums.begin(), nums.end());
	return nums;
}
---
Building a new vector and using an $O(n^2)$ sort is inefficient. The erase-remove idiom processes elements in-place in $O(n)$, and std::sort provides $O(n \log n)$ efficiency.

