output:
#include <vector>
#include <algorithm>

int find_max_product_pair(const std::vector<int>& nums) {
	if (nums.size() < 2) return 0;
	int max1 = -2147483648, max2 = -2147483648;
	int min1 = 2147483647, min2 = 2147483647;
	for (int x : nums) {
		if (x > max1) { max2 = max1; max1 = x; }
		else if (x > max2) max2 = x;
		if (x < min1) { min2 = min1; min1 = x; }
		else if (x < min2) min2 = x;
	}
	return std::max(max1 * max2, min1 * min2);
}
---
Brute force checking all pairs is $O(n^2)$. The maximum product must be either the product of the two largest numbers or the two smallest (most negative) numbers, found in $O(n)$ time.

