bool is_monotonic(const std::vector<int>& nums) {
	bool inc = true, dec = true;
	for (size_t i = 0; i < nums.size(); ++i) {
		for (size_t j = i + 1; j < nums.size(); ++j) {
			if (nums[i] > nums[j]) inc = false;
			if (nums[i] < nums[j]) dec = false;
		}
